192:     PFX(cpu_cpuid)(0, &max_basic_cap, vendor + 0, vendor + 2, vendor + 1);
193:     if (max_basic_cap == 0)
194:         return 0;
195: 
196:     PFX(cpu_cpuid)(1, &eax, &ebx, &ecx, &edx);
197:     if (edx & 0x00800000)
198:         cpu |= X265_CPU_MMX;
199:     else
200:         return cpu;
201:     if (edx & 0x02000000)
202:         cpu |= X265_CPU_MMX2 | X265_CPU_SSE;
203:     if (edx & 0x04000000)
204:         cpu |= X265_CPU_SSE2;
205:     if (ecx & 0x00000001)
206:         cpu |= X265_CPU_SSE3;
207:     if (ecx & 0x00000200)
208:         cpu |= X265_CPU_SSSE3 | X265_CPU_SSE2_IS_FAST;
209:     if (ecx & 0x00080000)
210:         cpu |= X265_CPU_SSE4;
211:     if (ecx & 0x00100000)
212:         cpu |= X265_CPU_SSE42;
213: 
214:     if (ecx & 0x08000000) /* XGETBV supported and XSAVE enabled by OS */
215:     {
216:         /* Check for OS support */
217:         xcr0 = PFX(cpu_xgetbv)(0);
218:         if ((xcr0 & 0x6) == 0x6) /* XMM/YMM state */
219:         {
220:             if (ecx & 0x10000000)
221:             cpu |= X265_CPU_AVX;
222:             if (ecx & 0x00001000)
223:                 cpu |= X265_CPU_FMA3;
224:         }
225:     }
226: 
227:     if (max_basic_cap >= 7)
228:     {
229:         PFX(cpu_cpuid)(7, &eax, &ebx, &ecx, &edx);
230:         /* AVX2 requires OS support, but BMI1/2 don't. */
231:         if (ebx & 0x00000008)
232:             cpu |= X265_CPU_BMI1;
233:         if (ebx & 0x00000100)
234:             cpu |= X265_CPU_BMI2;
235: 
236:         if ((xcr0 & 0x6) == 0x6) /* XMM/YMM state */
237:         {
238:             if (ebx & 0x00000020)
239:                 cpu |= X265_CPU_AVX2;
240:             if (benableavx512)
241:             {
242:                 if ((xcr0 & 0xE0) == 0xE0) /* OPMASK/ZMM state */
243:                 {
244:                     if ((ebx & 0xD0030000) == 0xD0030000)
245:                     {
246:                         cpu |= X265_CPU_AVX512;
247:                         enable512 = true;
248:                     }
249:                 }
250:             }
251:         }
252:     }
253: 
254:     PFX(cpu_cpuid)(0x80000000, &eax, &ebx, &ecx, &edx);
255:     max_extended_cap = eax;
256: 
257:     if (max_extended_cap >= 0x80000001)
258:     {
259:         PFX(cpu_cpuid)(0x80000001, &eax, &ebx, &ecx, &edx);
260: 
261:         if (ecx & 0x00000020)
262:             cpu |= X265_CPU_LZCNT; /* Supported by Intel chips starting with Haswell */
263:         if (ecx & 0x00000040) /* SSE4a, AMD only */
264:         {
265:             int family = ((eax >> 8) & 0xf) + ((eax >> 20) & 0xff);
266:             cpu |= X265_CPU_SSE2_IS_FAST;      /* Phenom and later CPUs have fast SSE units */
267:             if (family == 0x14)
268:             {
269:                 cpu &= ~X265_CPU_SSE2_IS_FAST; /* SSSE3 doesn't imply fast SSE anymore... */
270:                 cpu |= X265_CPU_SSE2_IS_SLOW;  /* Bobcat has 64-bit SIMD units */
271:                 cpu |= X265_CPU_SLOW_PALIGNR;  /* palignr is insanely slow on Bobcat */
272:             }
273:             if (family == 0x16)
274:             {
275:                 cpu |= X265_CPU_SLOW_PSHUFB;   /* Jaguar's pshufb isn't that slow, but it's slow enough
276:                                                 * compared to alternate instruction sequences that this
277:                                                 * is equal or faster on almost all such functions. */
278:             }
279:         }
280: 
281:         if (cpu & X265_CPU_AVX)
282:         {
283:             if (ecx & 0x00000800) /* XOP */
284:                 cpu |= X265_CPU_XOP;
285:             if (ecx & 0x00010000) /* FMA4 */
286:                 cpu |= X265_CPU_FMA4;
287:         }
288: 
289:         if (!strcmp((char*)vendor, "AuthenticAMD"))
290:         {
291:             if (edx & 0x00400000)
292:                 cpu |= X265_CPU_MMX2;
293:             if ((cpu & X265_CPU_SSE2) && !(cpu & X265_CPU_SSE2_IS_FAST))
294:                 cpu |= X265_CPU_SSE2_IS_SLOW; /* AMD CPUs come in two types: terrible at SSE and great at it */
295:         }
296:     }
297: 
298:     if (!strcmp((char*)vendor, "GenuineIntel"))
299:     {
300:         PFX(cpu_cpuid)(1, &eax, &ebx, &ecx, &edx);
301:         int family = ((eax >> 8) & 0xf) + ((eax >> 20) & 0xff);
302:         int model  = ((eax >> 4) & 0xf) + ((eax >> 12) & 0xf0);
303:         if (family == 6)
304:         {
305:             /* Detect Atom CPU */
306:             if (model == 28)
307:             {
308:                 cpu |= X265_CPU_SLOW_ATOM;
309:                 cpu |= X265_CPU_SLOW_PSHUFB;
310:             }
311: 
312:             /* Conroe has a slow shuffle unit. Check the model number to make sure not
313:              * to include crippled low-end Penryns and Nehalems that don't have SSE4. */
314:             else if ((cpu & X265_CPU_SSSE3) && !(cpu & X265_CPU_SSE4) && model < 23)
