324:         if (!cache && max_extended_cap >= 0x80000006)
325:         {
326:             PFX(cpu_cpuid)(0x80000006, &eax, &ebx, &ecx, &edx);
327:             cache = ecx & 0xff; // cacheline size
328:         }
329:         if (!cache && max_basic_cap >= 2)
