331:             // Cache and TLB Information
332:             static const char cache32_ids[] = { '\x0a','\x0c','\x41','\x42','\x43','\x44','\x45','\x82','\x83','\x84','\x85','\0' };
333:             static const char cache64_ids[] = { '\x22','\x23','\x25','\x29','\x2c','\x46','\x47','\x49','\x60','\x66','\x67',
334:                                                 '\x68','\x78','\x79','\x7a','\x7b','\x7c','\x7c','\x7f','\x86','\x87','\0' };
335:             uint32_t buf[4];
336:             int max, i = 0;
337:             do
338:             {
339:                 PFX(cpu_cpuid)(2, buf + 0, buf + 1, buf + 2, buf + 3);
340:                 max = buf[0] & 0xff;
341:                 buf[0] &= ~0xff;
342:                 for (int j = 0; j < 4; j++)
343:                 {
344:                     if (!(buf[j] >> 31))
345:                         while (buf[j])
346:                         {
347:                             if (strchr(cache32_ids, buf[j] & 0xff))
348:                                 cache = 32;
349:                             if (strchr(cache64_ids, buf[j] & 0xff))
350:                                 cache = 64;
351:                             buf[j] >>= 8;
352:                         }
353:                 }
354:             }
355:             while (++i < max);
356:         }
357: 
358:         if (cache == 32)
359:             cpu |= X265_CPU_CACHELINE_32;
360:         else if (cache == 64)
361:             cpu |= X265_CPU_CACHELINE_64;
362:         else
363:             x265_log(NULL, X265_LOG_WARNING, "unable to determine cacheline size\n");
364:     }
365: 
366: #if BROKEN_STACK_ALIGNMENT
367:     cpu |= X265_CPU_STACK_MOD4;
368: #endif
369: 
370:     return cpu;
371: }
