342: class Event
343: {
344: public:
345: 
346:     Event()
347:     {
348:         m_counter = 0;
349:         if (pthread_mutex_init(&m_mutex, NULL) ||
350:             pthread_cond_init(&m_cond, NULL))
351:         {
352:             x265_log(NULL, X265_LOG_ERROR, "fatal: unable to initialize conditional variable\n");
353:         }
354:     }
355: 
356:     ~Event()
357:     {
358:         pthread_cond_destroy(&m_cond);
359:         pthread_mutex_destroy(&m_mutex);
360:     }
361: 
362:     void wait()
363:     {
364:         pthread_mutex_lock(&m_mutex);
365: 
366:         /* blocking wait on conditional variable, mutex is atomically released
367:          * while blocked. When condition is signaled, mutex is re-acquired */
368:         while (!m_counter)
369:             pthread_cond_wait(&m_cond, &m_mutex);
370: 
371:         m_counter--;
372:         pthread_mutex_unlock(&m_mutex);
373:     }
374: 
375:     bool timedWait(uint32_t waitms)
376:     {
377:         bool bTimedOut = false;
378: 
379:         pthread_mutex_lock(&m_mutex);
380:         if (!m_counter)
381:         {
382:             struct timeval tv;
383:             struct timespec ts;
384:             gettimeofday(&tv, NULL);
385:             /* convert current time from (sec, usec) to (sec, nsec) */
386:             ts.tv_sec = tv.tv_sec;
387:             ts.tv_nsec = tv.tv_usec * 1000;
388: 
389:             ts.tv_nsec += 1000 * 1000 * (waitms % 1000);    /* add ms to tv_nsec */
390:             ts.tv_sec += ts.tv_nsec / (1000 * 1000 * 1000); /* overflow tv_nsec */
391:             ts.tv_nsec %= (1000 * 1000 * 1000);             /* clamp tv_nsec */
392:             ts.tv_sec += waitms / 1000;                     /* add seconds */
393: 
394:             /* blocking wait on conditional variable, mutex is atomically released
395:              * while blocked. When condition is signaled, mutex is re-acquired.
396:              * ts is absolute time to stop waiting */
397:             bTimedOut = pthread_cond_timedwait(&m_cond, &m_mutex, &ts) == ETIMEDOUT;
398:         }
399:         if (m_counter > 0)
400:         {
401:             m_counter--;
402:             bTimedOut = false;
403:         }
404:         pthread_mutex_unlock(&m_mutex);
405:         return bTimedOut;
406:     }
407: 
408:     void trigger()
409:     {
410:         pthread_mutex_lock(&m_mutex);
411:         if (m_counter < UINT_MAX)
412:             m_counter++;
413:         /* Signal a single blocking thread */
414:         pthread_cond_signal(&m_cond);
415:         pthread_mutex_unlock(&m_mutex);
416:     }
417: 
418: protected:
419: 
420:     pthread_mutex_t m_mutex;
421:     pthread_cond_t  m_cond;
422:     uint32_t        m_counter;
423: };
